import{z as d,x as B,o as s,c as A,q as E,j as o,D as r,d as t,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Christofides","description":"","frontmatter":{"title":"Christofides","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/christofides.md","filePath":"cs/christofides.md","lastUpdated":1791413859000}'),h={name:"cs/christofides.md"};function m(T,a,p,f,P,S){const i=B("Mermaid");return s(),A("div",null,[a[2]||(a[2]=E('<h1 id="christofides" tabindex="-1">Christofides <a class="header-anchor" href="#christofides" aria-label="Permalink to &quot;Christofides&quot;">​</a></h1><div class="epigraph"><p>度量 TSP：MST 加倍是 2-近似；对奇度点最小匹配再欧拉捷径，最坏 $3/2$。</p><footer>—— 据 Christofides, Worst-Case Analysis of a New Heuristic for the Travelling Salesman Problem, 1976；CLRS 第 35.2 节整理</footer></div><p>上一课<a href="/cs/set-cover-greedy">集合覆盖</a>的对数比是近似性的下限味道；度量 TSP 好得多——三角不等式换来常数比。主干<a href="/cs/hamiltonian-tsp-exact">哈密顿精确解</a>是指数时间；缺口是 Christofides 的 \\(3/2\\)。本课不重写 Held–Karp；后课 LP 舍入。注意一般非度量 TSP 无常数比近似（除非 P=NP）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先看两条热身事实：MST 权 \\(\\le\\mathrm{OPT}\\)（环删一边即成树）；把 MST 每条边加倍得欧拉图，沿欧拉环走、按三角不等式抄捷径，得 \\(2\\,\\mathrm{OPT}\\)——这是 MST 加倍法。<span class="marginnote">术语翻译：「奇度点」就是树上连着奇数条边的顶点；而欧拉回路（每条边恰好走一遍的环）要求每个点度数都是偶数。Christofides 的匹配一步，本质是给每个奇度点额外补一条边，把「奇」变成「偶」，好让欧拉环走得起来。</span>Christofides 只改一处：MST 的奇度顶点集 \\(O\\)（握手引理保证它是偶数个），在 \\(O\\) 上求最小权完美匹配 \\(M\\) 并入树。关键界是 \\(w(M)\\le\\mathrm{OPT}/2\\)：最优环限制到 \\(O\\) 上恰拆成两个完美匹配，较小者不超过 \\(\\mathrm{OPT}/2\\)。于是 \\(\\mathrm{MST}\\cup M\\) 欧拉，捷径后 \\(\\le\\mathrm{MST}+w(M)\\le 3/2\\,\\mathrm{OPT}\\)。</p><p>缺口正是「匹配」这一步，不是 MST 加倍那类 \\(2\\)-近似。</p><h3 id="必须度量" tabindex="-1">必须度量 <a class="header-anchor" href="#必须度量" aria-label="Permalink to &quot;必须度量&quot;">​</a></h3><p>必须度量：没有三角不等式，抄捷径这一步不成立——绕路的代价可能反而更小，保证全塌。城市距离天然满足；一般图可先取最短路闭包化成度量再用。</p><p><span class="marginnote">Christofides 1976。近年 \\(3/2-\\varepsilon\\) 的改进点名。后课 LP 舍入是另一近似范式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线：求 MST；收集奇度点，在它们导出的完全图上（边权用原度量）跑最小权匹配（<a href="/cs/hungarian-km">KM</a> 或一般带权匹配）；并回树后用 Hierholzer 走欧拉环；最后按三角不等式抄捷径去掉重复顶点。注意匹配跑在奇度点的度量完全图上，不是原稀疏图。</p>',11)),(s(),o(n,null,{default:r(()=>[l(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MST%5B%22MST%22%5D%20--%3E%20ODD%5B%22%E5%A5%87%E5%BA%A6%E7%82%B9%E5%8C%B9%E9%85%8D%22%5D%0A%20%20ODD%20--%3E%20EU%5B%22%E6%AC%A7%E6%8B%89%E5%9B%9E%E8%B7%AF%22%5D%0A%20%20EU%20--%3E%20SH%5B%22%E4%B8%89%E8%A7%92%E6%8D%B7%E5%BE%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"实现注意：匹配是度量完全图。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制核心一步：最优 TSP 环在每个奇度点恰用两条边，把环边交替染成两色，各得 \\(O\\) 上一个完美匹配，两匹配权之和不超过 \\(\\mathrm{OPT}\\)（限制到 \\(O\\) 的环抄过捷径，只会更短），较小者 \\(\\le\\mathrm{OPT}/2\\)。",-1)),a[6]||(a[6]=e("p",null,"「\\(w(M)\\le\\mathrm{OPT}/2\\)」这条关键界的来路：",-1)),(s(),o(n,null,{default:r(()=>[l(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOUR%5B%22%E6%9C%80%E4%BC%98%20TSP%20%E7%8E%AF%3A%20%E6%AF%8F%E4%B8%AA%E5%A5%87%E5%BA%A6%E7%82%B9%E6%81%B0%E8%BF%9E%E4%B8%A4%E6%9D%A1%E7%8E%AF%E8%BE%B9%22%5D%20--%3E%20ALT%5B%22%E6%B2%BF%E7%8E%AF%E6%8A%8A%E8%BE%B9%E4%BA%A4%E6%9B%BF%E6%9F%93%E6%88%90%E7%BA%A2%E8%93%9D%22%5D%0A%20%20ALT%20--%3E%20M1%5B%22%E7%BA%A2%E8%BE%B9%E9%9B%86%3A%20O%20%E4%B8%8A%E7%9A%84%E5%AE%8C%E7%BE%8E%E5%8C%B9%E9%85%8D%E4%B8%80%22%5D%0A%20%20ALT%20--%3E%20M2%5B%22%E8%93%9D%E8%BE%B9%E9%9B%86%3A%20O%20%E4%B8%8A%E7%9A%84%E5%AE%8C%E7%BE%8E%E5%8C%B9%E9%85%8D%E4%BA%8C%22%5D%0A%20%20M1%20--%3E%20SUM%5B%22%E4%B8%A4%E5%8C%B9%E9%85%8D%E6%9D%83%E4%B9%8B%E5%92%8C%20%E2%89%A4%20OPT%22%5D%0A%20%20M2%20--%3E%20SUM%0A%20%20SUM%20--%3E%20MIN%5B%22%E8%BE%83%E5%B0%8F%E8%80%85%20%3C%3D%20OPT%2F2%2C%20%E6%88%91%E4%BB%AC%E7%9A%84%20M%20%E5%8F%AA%E4%BC%9A%E6%9B%B4%E5%B0%8F%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>与欧拉课的呼应：欧拉回路要求全偶度，匹配恰好补齐奇度；边允许重复，走完再捷径。与精确 TSP 对照：Held–Karp 指数，这里多项式换 \\(1.5\\) 倍。<span class="marginnote">直觉类比：三角不等式下的「抄捷径」就像发现「北京→上海→广州」的总里程不会比「北京→广州」更短——绕道绝不占便宜。欧拉环里重复经过的城市全靠这一步抹掉，而它也是整个 \\(3/2\\) 证明里唯一用到度量条件的地方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开路径版 TSP（起终点不重合）的变体全文，不写欧氏实例的 PTAS（Arora）。后课默认：度量 TSP 有 \\(3/2\\) 的 Christofides。下一课 LP 松弛与舍入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>度量 TSP：MST+奇度匹配+\\(3/2\\)。<span class="marginnote">数字实例：\\(3/2\\) 的含义是「最坏情况的封顶」——若某实例的最优环是 100 公里，Christofides 给出的环再差也不会超过 150 公里；换成 MST 加倍法，同样的最坏封顶是 200 公里。具体实例上往往远好于封顶值。</span></li><li>无三角则无此保证。</li><li>精确仍 NPC。</li><li>出处：Christofides, 1976；CLRS 第 35.2 节。</li></ul>',5))])}const u=d(h,[["render",m]]);export{c as __pageData,u as default};
